CREATE TABLE "observability_metric_points" ("id" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "scope" TEXT NOT NULL, "scopeId" TEXT NOT NULL, "value" DECIMAL(18,4) NOT NULL, "bucketAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "observability_metric_points_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "observability_metric_points_metricKey_scope_scopeId_bucketAt_key" ON "observability_metric_points"("metricKey", "scope", "scopeId", "bucketAt");
CREATE INDEX "observability_metric_points_scope_scopeId_bucketAt_idx" ON "observability_metric_points"("scope", "scopeId", "bucketAt");
CREATE INDEX "observability_metric_points_metricKey_bucketAt_idx" ON "observability_metric_points"("metricKey", "bucketAt");
CREATE TABLE "observability_slos" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "scope" TEXT NOT NULL, "scopeId" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "targetPercentage" DECIMAL(6,3) NOT NULL, "windowDays" INTEGER NOT NULL, "owner" TEXT NOT NULL, "runbookUrl" TEXT NOT NULL, "notificationChannel" TEXT NOT NULL, "isEnabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "observability_slos_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "observability_slos_scope_scopeId_metricKey_key" ON "observability_slos"("scope", "scopeId", "metricKey");
CREATE INDEX "observability_slos_isEnabled_scope_scopeId_idx" ON "observability_slos"("isEnabled", "scope", "scopeId");
CREATE TABLE "observability_alert_history" ("id" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "metricKey" TEXT NOT NULL, "scope" TEXT NOT NULL, "scopeId" TEXT NOT NULL, "severity" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "value" DECIMAL(18,4) NOT NULL, "threshold" DECIMAL(18,4) NOT NULL, "owner" TEXT NOT NULL, "runbookUrl" TEXT NOT NULL, "notificationChannel" TEXT NOT NULL, "silencedUntil" TIMESTAMP(3), "openedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolvedAt" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "observability_alert_history_pkey" PRIMARY KEY ("id"));
CREATE INDEX "observability_alert_history_fingerprint_status_idx" ON "observability_alert_history"("fingerprint", "status");
CREATE INDEX "observability_alert_history_scope_scopeId_openedAt_idx" ON "observability_alert_history"("scope", "scopeId", "openedAt");
CREATE INDEX "observability_alert_history_status_silencedUntil_idx" ON "observability_alert_history"("status", "silencedUntil");
CREATE TABLE "deployment_markers" ("id" TEXT NOT NULL, "service" TEXT NOT NULL, "version" TEXT NOT NULL, "environment" TEXT NOT NULL, "description" TEXT, "deployedAt" TIMESTAMP(3) NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "deployment_markers_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "deployment_markers_service_version_environment_key" ON "deployment_markers"("service", "version", "environment");
CREATE INDEX "deployment_markers_deployedAt_idx" ON "deployment_markers"("deployedAt");
